const INTEGER = /^-?(0|[1-9][0-9]*)$/
const DURATION = /^(\d+)(ms|s|m|h)$/
const DURATION_MS = { ms: 1, s: 1000, m: 60000, h: 3600000 }

function coerceInteger(key, text) {
  if (!INTEGER.test(text)) return { ok: false, message: `${key} is not an integer: ${text}` }
  return { ok: true, rendered: text }
}

function coerceBoolean(key, text) {
  if (text !== 'true' && text !== 'false') return { ok: false, message: `${key} is not a boolean: ${text}` }
  return { ok: true, rendered: text }
}

function coerceEnum(key, members, text) {
  if (!members.includes(text)) return { ok: false, message: `${key} is not one of ${members.join('|')}: ${text}` }
  return { ok: true, rendered: text }
}

function coerceDuration(key, text) {
  const match = DURATION.exec(text)
  if (!match) return { ok: false, message: `${key} is not a duration: ${text}` }
  return { ok: true, rendered: String(Number(match[1]) * DURATION_MS[match[2]]) }
}

function coerceList(key, text) {
  if (text === '') return { ok: true, rendered: '' }
  const items = text.split(',').map(item => item.trim())
  if (items.some(item => item === '')) return { ok: false, message: `${key} has an empty item: ${text}` }
  const kept = []
  const seen = new Set()
  for (const item of items) {
    if (seen.has(item)) continue
    seen.add(item)
    kept.push(item)
  }
  return { ok: true, rendered: kept.join(',') }
}

/**
 * Coerce one setting's raw text by its declared type.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {{ok: true, rendered: string} | {ok: false, message: string}} the coercion result.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return { ok: true, rendered: text }
    case 'integer':
      return coerceInteger(declared.key, text)
    case 'boolean':
      return coerceBoolean(declared.key, text)
    case 'enum':
      return coerceEnum(declared.key, declared.members, text)
    case 'duration':
      return coerceDuration(declared.key, text)
    case 'list':
      return coerceList(declared.key, text)
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
}
