/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { coerce } from './coerce.js'
import { EnvError, parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { SETTINGS, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return { name, values: parseIni(readFileSync(path, 'utf8')) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/** Refuse the first key an INI layer sets that the schema does not know, in the order it was written. */
function checkKnown(path, values) {
  for (const [key, value] of values) {
    if (setting(key) === undefined) fail(`${path}:${value.line}:${value.column}: unknown setting ${key}`)
  }
}

/** The environment layer, read from standard input and refused at its own position. */
function envLayer(text) {
  try {
    return { name: 'env', values: parseEnv(text) }
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
}

/** Standard input's whole text, or the empty string when none was piped in. */
function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

/** The file and position an entry's value was written at, for a coercion failure's message. */
function where(entry, base, site) {
  if (entry.layer === 'env') return `<stdin>:${entry.value.line}:${entry.value.column}`
  const path = entry.layer === 'base' ? base : site
  return `${path}:${entry.value.line}:${entry.value.column}`
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

if (mode === 'dump' || mode === 'get') {
  const values = merge([iniLayer('file', argv[1])])
  const raw = key => (values.has(key) ? values.get(key).value.text : setting(key).default)
  const out = []
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
  process.stdout.write(out.map(line => `${line}\n`).join(''))
} else if (mode === 'load' || mode === 'origin') {
  const base = iniLayer('base', argv[1])
  checkKnown(argv[1], base.values)
  const site = iniLayer('site', argv[2])
  checkKnown(argv[2], site.values)
  const env = envLayer(readStdin())
  const values = merge([base, site, env])

  const out = []
  for (const declared of SETTINGS) {
    const entry = values.get(declared.key)
    if (mode === 'origin') {
      out.push(`${declared.key} ${entry ? entry.layer : 'default'}`)
    } else {
      const text = entry ? entry.value.text : declared.default
      const result = coerce(declared, text)
      if (!result.ok) fail(`${where(entry, argv[1], argv[2])}: ${result.message}`)
      out.push(`${declared.key}=${result.rendered}`)
    }
  }
  process.stdout.write(out.map(line => `${line}\n`).join(''))
}
"}

